style.css:
@-moz-document domain("www.xiaoqiqiao.com") {
* {
        color: rgba(0, 0, 0, 0.85)!important; /* 设置文字颜色为rgba(0, 0, 0, 0.85) */
        font-weight: normal!important; /* 设置文字为常规粗细，去除加粗效果 */
        font-family: "宋体"!important; /* 设置字体为宋体 */
        letter-spacing: 1px!important; /* 设置文字间隔为2像素，可根据需要调整数值 */
    }
}
